function nextScene(){if(game.fadeDir)return;game.locked=true;game.interact=null;ui.prompt.classList.add('hidden');game.fadeDir=1}
function sceneArrival(){game.sceneIntro=120;if(game.scene===1){game.plane=-220;game.planeSoundPlayed=false;say('Fred','The house behind me is gone. Two engines rumble somewhere above the smoke.')}if(game.scene===3)say('Fred','This used to be a clinic. Why are all the beds empty?');if(game.scene===4)say('BLACKBOARD','Does peace begin on the day the war ends?',()=>say('FRED','A family photograph lies on the desk. Six torn pieces are scattered through this classroom. I should put it back together.',()=>{game.locked=false}));if(game.scene===5)say('Fred','The radio should be silent. Beneath the static, a calm voice is trying to reach me.',()=>startTuning());if(game.scene===6)say('Fred','There is light beyond the gate. If I can cross the square…')}
function startTuning(){
 game.locked=true;ui.tuning.querySelector('p').textContent='TUNE THROUGH THE STATIC · FIND THE STEADY VOICE';ui.tuning.classList.remove('hidden');
 const target=18+Math.floor(Math.random()*65),tolerance=2,start=target>50?target-24:target+24;
 ui.freq.value=start;ui.tuning.querySelector('small').textContent='STATIC — A DISTANT SIREN BENEATH AN ORDINARY VOICE';
 ui.freq.oninput=()=>{const v=+ui.freq.value,diff=Math.abs(v-target);ui.tuning.querySelector('small').textContent=diff<=tolerance?'…Fred? It is eight o’clock. Your tea has gone cold…':diff<=9?'An ordinary voice is beginning to emerge…':'STATIC — A DISTANT SIREN BENEATH AN ORDINARY VOICE'};
 ui.freq.onchange=()=>{const v=+ui.freq.value;if(Math.abs(v-target)<=tolerance){ui.tuning.classList.add('hidden');ask(10,continueAfterTuning)}};
}
function continueAfterTuning(n){const replies=['The room around me has sounds of its own. I want to hear them.','For a moment, the two voices overlap. I cannot tell where one ends.','The siren swallows the room again. I almost forget there is anything else.'];say('FRED',replies[n],()=>ask(11,n=>{if(n===2){game.x=80;say('FRED','The signal recedes. I am back where the broadcast began.',()=>{game.locked=false;game.event=1})}else{game.locked=false;game.event=1}}))}
