function startChase(){
 const shelter=game.scene===5;
 const line=shelter
  ? 'The broadcast fades. The tunnel is quiet now; only your footsteps remain.'
  : 'The broadcast fades. In the sudden silence, the old fear rushes in.';
 say('',line,()=>{
  game.locked=false;
  if(shelter){
   // Act 6 is a listening and navigation sequence, not a boss encounter.
   // Clear any legacy chase state so the player can leave the shelter normally.
   game.boss=false;game.bossT=0;
   ui.prompt.textContent='KEEP MOVING RIGHT · THE EXIT IS AHEAD';
  }else{
   game.boss='chase';game.bossT=-180;
   ui.prompt.textContent='RUN FOR THE EXIT · THE FOG IS GATHERING';
  }
  ui.prompt.classList.remove('hidden');
 })
}
